import {CHALLENGES} from './operations.js';
import {notify} from './hud.js';
import {hostActionError,cleanName} from './play-rules.js';
import * as THREE from './three.module.js';
import {createAvatar} from './avatar.js';
export function createMultiplayer({scene,camera,world,network,onWorld,closePanels}){
 const $=id=>document.getElementById(id);let playerList=[],slot=0;let selfID=null,token=null,revision=-1,stream=null,healthy=false,busy=false,elapsed=0,modal=false;const models=new Map(),pings=new Map();let role='field',roleUpdate=Promise.resolve(),chatOpen=false,historyOpen=false;const messages=[];let soloSelected=false;let rosterKey='',chatElapsed=0,lastPose=null,lastPoseAt=0;let roomServer=null,hostAccess=false,onSession=()=>{};
 const canManageWorld=()=>(roomServer===false||soloSelected)&&!token||!!token&&hostAccess;
 fetch('/api/room').then(async r=>{if(r.status===404){roomServer=false;return;}if(!r.ok)throw Error('Room detection failed');if(!r.headers.get('content-type')?.includes('application/json')){roomServer=false;return;}const d=await r.json();roomServer=d.protocol==='infra-lan-v1';if(d.localHost)await joinRoom({name:'Host Engineer',code:d.roomCode,hostKey:d.hostKey},true);}).catch(e=>{roomServer=true;$('lan-status').textContent='LAN host detection failed: '+e.message;}).finally(()=>onWorld());
 document.getElementById('game-bar').insertAdjacentHTML('beforeend','<button id="lan-button">LAN co-op · 1/12</button>');
 document.body.insertAdjacentHTML('beforeend',`<section id="lan-panel" hidden aria-label="LAN multiplayer"><div class="lab-head"><b>LAN CO-OP · 12 PLAYERS MAX</b><button id="lan-close">×</button></div><p id="lan-status">Open the site from the local host computer’s server address to play together.</p><label>Player name<input id="lan-name" maxlength="20" value="Engineer"></label><label>Room code<input id="lan-code" maxlength="32" autocomplete="off" placeholder="Ask the host"></label><label>Host key (host only)<input id="lan-host-key" type="password" autocomplete="off" placeholder="Guests leave this empty"></label><div class="lab-actions"><button id="lan-join">Join room</button><button id="lan-leave" hidden>Leave room</button></div><ol id="lan-roster"></ol><div id="lan-host-controls" hidden><strong>Host lobby</strong><span id="lan-host-count"></span><p>Wait until your team joins, then choose the shared mode.</p><button id="lan-start-campaign">Start campaign</button><button id="lan-start-free">Start free play</button><label>Challenge<select id="lan-challenge">${CHALLENGES.map((name,i)=>`<option value="${i}">${i+1}. ${name}</option>`).join('')}</select></label><button id="lan-start-challenge">Prepare selected challenge</button><button id="lan-start-enterprise">Start enterprise office</button></div><div id="lan-events"></div><details><summary>Host a local room</summary><p>Use the LAN package. Install Node.js, open its folder in Terminal, and run:</p><code>node lan/server.mjs</code><p>Share the address and room code printed there. Keep the separate host key private; it unlocks game mode and campaign save controls, not engineer skills. Everyone must use that address on the same LAN. The room supports 12 players including the host. No internet matchmaking.</p></details></section>`);
 document.body.insertAdjacentHTML('beforeend',`<section id="team-chat" aria-label="Team chat"><div id="chat-history"></div><form id="chat-form" hidden><label for="chat-input">TEAM</label><input id="chat-input" maxlength="200" autocomplete="off" placeholder="Message your team…"></form></section>`);
 function drawChat(){const now=Date.now();$('chat-history').replaceChildren(...messages.filter(m=>historyOpen||now-m.at<9000).slice(historyOpen?-12:-3).map(m=>{const line=document.createElement('p'),who=document.createElement('strong'),body=document.createElement('span');who.textContent=m.name+': ';who.style.color='#'+Number(m.color).toString(16).padStart(6,'0');body.textContent=m.text;line.append(who,body);line.style.opacity=historyOpen?'1':String(Math.min(1,(9000-(now-m.at))/2000));return line;}));}
 function receiveChat(m){messages.push(m);if(messages.length>32)messages.shift();drawChat();}
 function openChat(history=false){if(!token){notify('Join a LAN room to chat');return;}chatOpen=!history;historyOpen=history;$('chat-form').hidden=history;if(document.pointerLockElement)document.exitPointerLock();if(!history)$('chat-input').focus();drawChat();}
 function closeChat(){chatOpen=false;historyOpen=false;$('chat-form').hidden=true;$('chat-input').value='';drawChat();}
 $('chat-form').onsubmit=async e=>{e.preventDefault();const value=$('chat-input').value.trim();if(!value){closeChat();return;}try{await post('chat',{text:value});closeChat();}catch(e){notify(e.message);}};
 $('chat-input').addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();closeChat();}});
 function receivePing(p){const old=pings.get(p.player);if(old){scene.remove(old.g);old.g.material.map.dispose();old.g.material.dispose();}const c=document.createElement('canvas');c.width=512;c.height=160;const x=c.getContext('2d');x.fillStyle='#'+Number(p.color).toString(16).padStart(6,'0');x.font='bold 28px sans-serif';x.textAlign='center';x.fillText(p.name+' PING',256,55);x.font='24px sans-serif';x.fillText(p.label.slice(0,32),256,105);const g=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(c),transparent:true,depthTest:false}));g.position.set(p.x,p.y+1,p.z);g.scale.set(5,1.55,1);scene.add(g);pings.set(p.player,{g,until:Date.now()+6500});}
 async function ping(target){if(!token){notify('Join a LAN room to ping teammates');return;}try{await post('ping',target);}catch(e){notify(e.message);}}
 // Rename yourself; the host cleans the name and every player's roster, chat and name tag update.
 function setName(value){const name=cleanName(value);$('lan-name').value=name;if(!token)return Promise.resolve({name});return post('name',{name}).catch(e=>{notify(e.message);return {error:e.message};});}
 function setRole(value){role=value;if(token)roleUpdate=post('role',{role:value}).catch(e=>{notify(e.message);return {error:e.message};});return roleUpdate;}
 function visible(open){modal=open;$('lan-panel').hidden=!open;if(open){closePanels();if(document.pointerLockElement)document.exitPointerLock();}}
 $('lan-button').onclick=()=>visible(!modal);$('lan-close').onclick=()=>visible(false);
 function state(data){const newer=data.revision>revision;if(newer&&data.events?.[0]&&/Mounted|mounted|configured|Applied|connected|installed|removed|replaced/.test(data.events[0]))notify(data.events[0]);if(data.world&&data.revision>revision){revision=data.revision;world.restore(data.world);onWorld();}if(data.events){$('lan-events').replaceChildren(...data.events.map(t=>{const p=document.createElement('p');p.textContent=t;return p;}));}}
 // Remote engineer: cartoon scout avatar (avatar.js) in the player's colour, animated from the pose stream.
 function avatar(p){const a=createAvatar({color:p.color,name:p.name||'ENGINEER-0'+(p.slot+1),face:p.pose.face,skin:p.pose.skin});scene.add(a.g);return Object.assign(a,{target:new THREE.Vector3(p.pose.x,0,p.pose.z),yaw:p.pose.yaw,crouch:p.pose.crouched,laptop:!!p.pose.laptop,emoteN:p.pose.emote?.n??0,prev:new THREE.Vector3(),speed:0,last:p.pose});}
 function dispose(m){m.dispose();}
 function players(list){playerList=list;slot=list.find(p=>p.id===selfID)?.slot??0;const present=new Set();for(const p of list){if(p.id===selfID)continue;present.add(p.id);let model=models.get(p.id);if(model&&(p.pose.skin||'yellow')!==model.skin){dispose(model);models.delete(p.id);model=null;}if(!model){model=avatar(p);model.g.position.copy(model.target);models.set(p.id,model);}model.target.set(p.pose.x,Math.max(0,p.pose.y-(p.pose.crouched?5.9:9.7)),p.pose.z);model.yaw=p.pose.yaw;model.crouch=p.pose.crouched;model.laptop=!!p.pose.laptop;if(p.name)model.setName(p.name);if(p.pose.face&&p.pose.face!==model.style)model.setStyle(p.pose.face);model.g.visible=p.pose.active;const e=p.pose.emote;if(e&&e.n!==model.emoteN){model.emoteN=e.n;model.play(e.id||null);}}
 for(const [id,m]of models)if(!present.has(id)){dispose(m);models.delete(id);}const key=JSON.stringify(list.map(p=>[p.id,p.name,p.pose.active]));if(key!==rosterKey){rosterKey=key;$('lan-roster').replaceChildren(...list.map(p=>{const li=document.createElement('li');li.textContent=p.name+(p.id===selfID?' (you)':'')+(p.pose.active?' · in game':' · inspecting');return li;}));$('lan-host-controls')&&($('lan-host-controls').hidden=!hostAccess,$('lan-host-count').textContent=list.length+' engineer(s) connected');$('lan-button').textContent=token?`LAN co-op · ${list.length}/12`:'LAN co-op · 1/12';}}
 async function post(route,body){const res=await fetch('/api/'+route,{method:'POST',headers:{'Content-Type':'application/json',...(token?{'X-Player-Token':token}:{})},body:JSON.stringify(body)});const data=await res.json();if(!res.ok){if(data.world)state(data);throw new Error(data.error||'LAN request failed');}return data;}
 async function send(action){const denied=hostActionError(hostAccess,action);if(denied){notify(denied);return denied;}if(!token||!healthy)return 'LAN connection unavailable. Wait for reconnection or leave the room.';try{await roleUpdate;const data=await post('action',{revision,action});state(data);return data.result??data.message;}catch(e){$('lan-status').textContent=e.message;return e.message;}}
 function leave(){if(token)post('leave',{}).catch(()=>{});stream?.close();stream=null;token=null;hostAccess=false;healthy=false;rosterKey='';playerList=[];network.setSubmit(null);for(const m of models.values())dispose(m);models.clear();$('lan-leave').hidden=true;$('lan-join').disabled=false;$('lan-button').textContent='LAN co-op · 1/12';$('lan-roster').replaceChildren();$('lan-status').textContent='Disconnected. Rejoin to work in the shared room.';onWorld();onSession();}
 $('lan-leave').onclick=leave;for(const pair of [['lan-start-campaign','campaign'],['lan-start-free','free'],['lan-start-challenge','challenge'],['lan-start-enterprise','campaign']]){const b=$(pair[0]);if(b)b.onclick=async()=>{const out=await send({type:'engineering',action:{type:'mode',mode:pair[1],enterprise:pair[0]==='lan-start-enterprise',name:'LAN Campaign',index:+$('lan-challenge').value}});if(String(out).startsWith('Empty facility')||String(out).startsWith('Healthy environment')){visible(false);onWorld();}};}
 async function joinRoom(credentials,automatic=false){if(token)return;$('lan-join').disabled=true;try{const check=await fetch('/api/room');if(!check.ok)throw new Error('Local server not running here. Open the host address from the LAN package.');const info=await check.json();if(info.protocol!=='infra-lan-v1')throw new Error('Use the LAN server address.');roomServer=true;const data=await post('join',{hostKey:credentials.hostKey||'',name:credentials.name||'Engineer',code:String(credentials.code||'').trim().toUpperCase()});soloSelected=false;token=data.token;hostAccess=data.isHost===true;$('lan-host-key').value='';$('lan-code').value=credentials.code||'';$('lan-name').value=credentials.name||'Engineer';selfID=data.id;revision=-1;state(data);players(data.players);network.setSubmit(send);healthy=true;$('lan-leave').hidden=false;$('lan-status').textContent=data.isHost?(automatic?'Local host connected automatically · Campaign controls unlocked':'Connected as host · Campaign controls unlocked'):'Connected. Players share cables, VLANs, port states and workloads.';stream=new EventSource('/api/events?token='+encodeURIComponent(token));stream.addEventListener('players',e=>players(JSON.parse(e.data)));stream.addEventListener('world',e=>state(JSON.parse(e.data)));stream.addEventListener('chat',e=>receiveChat(JSON.parse(e.data)));stream.addEventListener('ping',e=>receivePing(JSON.parse(e.data)));setRole(role);stream.onopen=()=>{healthy=true;$('lan-status').textContent=hostAccess?'Connected as host · Campaign controls unlocked':'Connected · shared room state';};stream.onerror=()=>{healthy=false;$('lan-status').textContent='Connection interrupted. Reconnecting… Leave and rejoin if the host restarted.';};onWorld();onSession();}catch(e){$('lan-status').textContent=e.message;$('lan-join').disabled=false;}}
 $('lan-join').onclick=()=>joinRoom({hostKey:$('lan-host-key').value,name:$('lan-name').value,code:$('lan-code').value});
 function update(dt,active,crouched,extras={}){elapsed+=dt;chatElapsed+=dt;if(chatElapsed>.25){chatElapsed=0;drawChat();}for(const [id,p]of pings){p.g.material.opacity=Math.min(1,(p.until-Date.now())/1500);if(Date.now()>p.until){scene.remove(p.g);p.g.material.map.dispose();p.g.material.dispose();pings.delete(id);}}for(const m of models.values()){m.prev.copy(m.g.position);m.g.position.lerp(m.target,1-Math.exp(-dt*14));const moved=Math.hypot(m.g.position.x-m.prev.x,m.g.position.z-m.prev.z);m.speed=dt>0?moved/dt:0;const current=m.g.rotation.y,difference=Math.atan2(Math.sin(m.yaw-current),Math.cos(m.yaw-current));m.g.rotation.y+=difference*(1-Math.exp(-dt*14));const far=m.g.position.distanceTo(camera.position);m.label.visible=far<28;if(m.g.visible&&far<90)m.update(dt,{speed:m.speed,crouch:m.crouch,laptop:m.laptop});}
 if(token&&elapsed>.12&&!busy){elapsed=0;busy=true;const rotation=new THREE.Euler().setFromQuaternion(camera.quaternion,'YXZ');const pose={x:camera.position.x,y:camera.position.y,z:camera.position.z,yaw:rotation.y,crouched,active,laptop:!!extras.laptop,face:extras.face||'cute',skin:extras.skin||'yellow',emote:extras.emote||{id:null,n:0}};if(lastPose&&Date.now()-lastPoseAt<2000&&Math.abs(pose.x-lastPose.x)+Math.abs(pose.y-lastPose.y)+Math.abs(pose.z-lastPose.z)<.015&&Math.abs(pose.yaw-lastPose.yaw)<.003&&pose.active===lastPose.active&&pose.crouched===lastPose.crouched&&pose.laptop===lastPose.laptop&&pose.face===lastPose.face&&pose.skin===lastPose.skin&&pose.emote.n===lastPose.emote?.n){busy=false;return;}lastPose=pose;lastPoseAt=Date.now();post('pose',{pose}).catch(e=>{$('lan-status').textContent=e.message;healthy=false;}).finally(()=>busy=false);}}
 return {setName,setOnSession(fn){onSession=fn;},playSolo(){soloSelected=true;leave();},openLobby:()=>visible(true),get canManageWorld(){return canManageWorld();},setRole,ping,openChat,closeChat,get chatOpen(){return chatOpen||historyOpen;},get players(){return playerList;},get slot(){return slot;},get selfID(){return selfID;},get connected(){return !!token;},get isOpen(){return modal||chatOpen||historyOpen;},send,update,leave,hide:()=>visible(false)};
}
